 <!DOCTYPE html>
 <html lang="en">
 <head>
   <meta charset="UTF-8">
   <meta name="viewport" content="width=device-width, initial-scale=1.0">
   <title>Support Contact Form</title>
   <style>
     :root {
       color-scheme: dark;
       --bg: #0b1020;
       --panel: rgba(17, 24, 39, 0.92);
       --panel-border: rgba(148, 163, 184, 0.2);
       --text: #e5eefc;
       --muted: #94a3b8;
       --input: rgba(15, 23, 42, 0.9);
       --input-border: rgba(148, 163, 184, 0.22);
       --input-focus: #60a5fa;
       --error: #fda4af;
       --button-start: #3b82f6;
       --button-end: #2563eb;
       --shadow: 0 24px 70px rgba(15, 23, 42, 0.45);
     }

     * {
       box-sizing: border-box;
     }

     body {
       margin: 0;
       min-height: 100vh;
       font-family: Arial, Helvetica, sans-serif;
       background:
         radial-gradient(circle at top, rgba(59, 130, 246, 0.18), transparent 35%),
         linear-gradient(180deg, #0f172a 0%, #020617 100%);
       color: var(--text);
       display: grid;
       place-items: center;
       padding: 32px 16px;
     }

     .support-card {
       width: min(100%, 540px);
       background: var(--panel);
       border: 1px solid var(--panel-border);
       border-radius: 24px;
       box-shadow: var(--shadow);
       backdrop-filter: blur(14px);
       padding: 32px;
     }

     .eyebrow {
       margin: 0 0 10px;
       color: #93c5fd;
       font-size: 0.8rem;
       font-weight: 700;
       letter-spacing: 0.08em;
       text-transform: uppercase;
     }

     h1 {
       margin: 0 0 12px;
       font-size: clamp(1.8rem, 4vw, 2.4rem);
       line-height: 1.15;
     }

     .intro {
       margin: 0 0 28px;
       color: var(--muted);
       line-height: 1.6;
     }

     form {
       display: grid;
       gap: 18px;
     }

     .form-field {
       display: grid;
       gap: 8px;
     }

     label {
       font-weight: 700;
       font-size: 0.96rem;
     }

     input {
       width: 100%;
       border: 1px solid var(--input-border);
       border-radius: 14px;
       background: var(--input);
       color: var(--text);
       padding: 14px 16px;
       font-size: 1rem;
       transition: border-color 160ms ease, box-shadow 160ms ease, transform 160ms ease;
     }

     input::placeholder {
       color: #64748b;
     }

     input:focus {
       outline: none;
       border-color: var(--input-focus);
       box-shadow: 0 0 0 4px rgba(96, 165, 250, 0.18);
       transform: translateY(-1px);
     }

     .field-help,
     .field-error {
       margin: 0;
       font-size: 0.92rem;
       line-height: 1.45;
     }

     .field-help {
       color: var(--muted);
     }

     .field-error {
       color: var(--error);
       display: none;
     }

     .form-field.invalid .field-error {
       display: block;
     }

     .form-field.invalid input {
       border-color: rgba(251, 113, 133, 0.9);
       box-shadow: 0 0 0 4px rgba(251, 113, 133, 0.12);
     }

     button {
       border: 0;
       border-radius: 14px;
       padding: 15px 18px;
       font-size: 1rem;
       font-weight: 700;
       color: #eff6ff;
       background: linear-gradient(135deg, var(--button-start), var(--button-end));
       cursor: pointer;
       transition: transform 160ms ease, box-shadow 160ms ease, filter 160ms ease;
       box-shadow: 0 16px 30px rgba(37, 99, 235, 0.32);
     }

     button:hover {
       filter: brightness(1.06);
       transform: translateY(-1px);
     }

     button:active {
       transform: translateY(0);
     }
   </style>
 </head>
 <body>
   <section class="support-card" aria-labelledby="support-title">
     <p class="eyebrow">Support</p>
     <h1 id="support-title">Contact our support team</h1>
     <p class="intro">Tell us how we can help and we’ll get back to you as soon as possible.</p>

     <form id="support-form" novalidate>
       <div class="form-field">
         <label for="full-name">Full name</label>
         <input id="full-name" name="fullName" type="text" placeholder="Jamie Rivera" required>
         <p class="field-error" aria-live="polite"></p>
       </div>

       <div class="form-field">
         <label for="email-address">Email address</label>
         <input id="email-address" name="email" type="email" placeholder="jamie@example.com" required>
         <p class="field-error" aria-live="polite"></p>
       </div>

       <div class="form-field">
         <label for="phone-number">Phone number</label>
         <input id="phone-number" name="phone" type="tel" placeholder="(555) 123-4567" inputmode="tel">
         <p class="field-help">Optional. Use a format like (555) 123-4567 or +1 555 123 4567.</p>
         <p class="field-error" aria-live="polite"></p>
       </div>

       <button type="submit">Submit request</button>
     </form>
   </section>

   <script>
     const form = document.getElementById('support-form');
     const fields = Array.from(form.querySelectorAll('.form-field'));

     const getErrorMessage = (input) => {
       const value = input.value.trim();

       if (input.name === 'fullName' && !value) {
         return 'Please enter your full name.';
       }

       if (input.name === 'email') {
         if (!value) {
           return 'Please enter your email address.';
         }

         if (input.validity.typeMismatch) {
           return 'Please enter a valid email address.';
         }
       }

       if (input.name === 'phone' && value) {
         const phonePattern = /^\+?[\d\s().-]{7,}$/;

         if (!phonePattern.test(value)) {
           return 'Enter a phone number using digits, spaces, parentheses, dots, or dashes.';
         }
       }

       return '';
     };

     const updateFieldState = (field) => {
       const input = field.querySelector('input');
       const error = field.querySelector('.field-error');
       const message = getErrorMessage(input);

       field.classList.toggle('invalid', Boolean(message));
       error.textContent = message;
     };

     fields.forEach((field) => {
       const input = field.querySelector('input');

       input.addEventListener('input', () => {
         if (field.classList.contains('invalid')) {
           updateFieldState(field);
         }
       });

       input.addEventListener('blur', () => {
         updateFieldState(field);
       });
     });

     form.addEventListener('submit', (event) => {
       fields.forEach(updateFieldState);

       const hasErrors = fields.some((field) => field.classList.contains('invalid'));

       if (hasErrors) {
         event.preventDefault();
       }
     });
   </script>
 </body>
